import{z as l,x as C,o as t,c as d,q as r,j as i,D as A,d as s,s as o,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"802.11 帧与 OFDM","description":"","frontmatter":{"title":"802.11 帧与 OFDM","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/wifi-frames-ofdm.md","filePath":"cs/wifi-frames-ofdm.md","lastUpdated":1791063341000}'),B={name:"cs/wifi-frames-ofdm.md"};function p(D,a,m,S,f,M){const E=C("Mermaid");return t(),d("div",null,[a[2]||(a[2]=r('<h1 id="_802-11-帧与-ofdm" tabindex="-1">802.11 帧与 OFDM <a class="header-anchor" href="#_802-11-帧与-ofdm" aria-label="Permalink to &quot;802.11 帧与 OFDM&quot;">​</a></h1><div class="epigraph"><p>无线没有可靠的载波碰撞检测，帧要带时长预约；OFDM 把宽带切成许多正交子载波，对抗频率选择性衰落。</p><footer>—— 据 IEEE 802.11；Weinstein and Ebert, OFDM, IEEE Trans. Commun. 1971；Kurose and Ross 无线章整理</footer></div><p>上一课序在<a href="/cs/output-queue-hol">输出排队与 HOL</a> 收束有线交换。主干<a href="/cs/csma-ca">CSMA/CA</a> 已给过退避。缺口是<strong>帧怎么占空中、物理层怎么占频谱</strong>：802.11 MAC 头、NAV、ACK；PHY 从 DSSS 走到 OFDM。本课不把 MIMO 矩阵写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>以太网全双工点到点几乎不冲突；无线是半双工共享介质，隐终端让 CD 不可靠，故 CA + RTS/CTS 预约。帧：帧控制、地址（可到四个，因为有 DS）、序号、FCS。数据帧后 SIFS 跟 ACK，失败才重传——这是链路努力，不是 TCP 的替代。OFDM：高 \\(R_s\\) 在多径下 ISI 严重，改用慢符号率的多子载波，循环前缀吃掉时延扩展。容量仍是 \\(B\\) 与 SNR，只是 \\(B\\) 被切成子信道。</p><p><span class="marginnote">数字实例：802.11a 的 SIFS 是 16 微秒，比 DIFS 的 34 微秒短——所以 ACK 和 CTS 总能抢在其他竞争者开口前发出，这就是「短间隔护航」的设计。</span></p><p><span class="marginnote">802.11a/g/n/ac 的 PHY 都以 OFDM 为骨干。地址字段服务基础设施 BSS：AP 与 DS。本课不把每个 subtype 背完。</span></p><h3 id="无线-ack-不取消-tcp" tabindex="-1">无线 ACK 不取消 TCP <a class="header-anchor" href="#无线-ack-不取消-tcp" aria-label="Permalink to &quot;无线 ACK 不取消 TCP&quot;">​</a></h3><p>CA 补不能可靠 CD。OFDM 用多子载波抗多径。MCS 阶梯是离散工作点，瞬时 \\(C\\) 随衰落变。AP 桥到有线，不是全国洪泛。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：DCF 听信道 → 发 → ACK；并行画：比特 → 编码交织 → 映到子载波 → IFFT → 加 CP。对照有线 PAM：无线必须估计每子载波信道。速率集（6–54 Mb/s 等）是调制编码方案，下一课自适应。</p><p><span class="marginnote">术语翻译：循环前缀（CP）就是「把符号尾巴复制一份垫在开头」——多径反射迟到的那点能量落进 CP 这段缓冲区，不再污染下一个符号，各子载波的正交性得以保住。</span></p>',12)),(t(),i(n,null,{default:A(()=>[o(E,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAC%5B%22802.11%20MAC%20%E5%B8%A7%22%5D%20--%3E%20CSMA%5B%22CSMA%2FCA%20%E4%B8%8E%20NAV%22%5D%0A%20%20MAC%20--%3E%20OFDM%5B%22%E5%AD%90%E8%BD%BD%E6%B3%A2%E6%98%A0%E5%B0%84%22%5D%0A%20%20OFDM%20--%3E%20AIR%5B%22%E7%A9%BA%E4%B8%AD%22%5D%0A%20%20AIR%20--%3E%20ACK%5B%22SIFS%20%E5%90%8E%20ACK%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"有线链路预算是电缆长度；这里是距离、遮挡、干扰。交换机学有线 MAC；无线客户端经 AP 桥到有线侧，AP 是翻译，不是 WDM 模块。巨帧在无线上更易错，重传代价高，故常保持较小 MSDU。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：RTS/CTS 像进会议室先喊一嗓子「我要讲 3 分钟，请大家安静」——AP 一跳内所有人都记下这段时间别开口；哪怕听不清讲话内容的人（隐终端）收到了这声「清场」，也知道别插话。")],-1)),(t(),i(n,null,{default:A(()=>[o(E,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E9%9A%90%E7%BB%88%E7%AB%AF%20B%20%E5%9C%A8%20A%20%E7%9A%84%E5%B0%84%E7%A8%8B%E5%A4%96%22%5D%20-.-%3E%7C%22%E5%90%AC%E4%B8%8D%E5%88%B0%20A%20%E5%8F%91%E5%8C%85%22%7C%20NAV%5B%22B%20%E8%AE%B0%20NAV%EF%BC%9A%E6%AD%A4%E6%AE%B5%E9%9D%99%E9%BB%98%22%5D%0A%20%20A%5B%22A%20%E8%A6%81%E5%8F%91%E6%95%B0%E6%8D%AE%E7%BB%99%20AP%22%5D%20--%3E%20R%5B%22%E5%85%88%E5%8F%91%20RTS%EF%BC%8C%E5%B8%A6%E6%97%B6%E9%95%BF%E5%AD%97%E6%AE%B5%22%5D%0A%20%20R%20--%3E%20C%5B%22AP%20%E5%9B%9E%20CTS%EF%BC%8C%E5%91%A8%E5%9B%B4%E9%83%BD%E5%90%AC%E5%88%B0%22%5D%0A%20%20C%20--%3E%20NAV%0A%20%20NAV%20--%3E%20SEND%5B%22A%20%E5%8F%91%E6%95%B0%E6%8D%AE%E5%B8%A7%22%5D%0A%20%20SEND%20--%3E%20ACK%5B%22AP%20%E5%9C%A8%20SIFS%20%E5%90%8E%E5%9B%9E%20ACK%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>容量课的 \\(C\\) 对时变信道是瞬间量，802.11 用 MCS 阶梯逼近。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 802.11ax 的 OFDMA 调度。MIMO 与速率自适应是下一课。后课默认：Wi‑Fi 数据面是 MAC 重传 + OFDM 比特加载。</p><p>不要把 Wi‑Fi 当蜂窝核心网：没有 RAN 切片，本课序后部才到 5G。</p><p>下一课<a href="/cs/mimo-rate-adaptation">MIMO 与速率自适应</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CA + ACK 补上无线不能可靠 CD 的缺口。</li><li>OFDM 用多子载波对抗多径 ISI。</li><li>链路 ACK 不取消 TCP。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 802.11；Weinstein–Ebert；Kurose and Ross。</li></ul>',7))])}const h=l(B,[["render",p]]);export{c as __pageData,h as default};
